@Component("healthSystem-handler")
@ProcessingGroup("healthSystem-processing-group")
public class HealthSystemEventHandler {
	
	// core constructor
	HealthSystemEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateHealthSystemEvent
     */
    @EventHandler
    public void handle( CreateHealthSystemEvent event) {
        entityManager.persist(new HealthSystem(event.getHealthSystemId(), event.getName(), event.getLegalName(), event.getHeadquartersCountry(), event.getWebsite(), event.getFacilities(), event.getSuppliers()));
    }

    /*
     * @param	event UpdateHealthSystemEvent
     */
    @EventHandler
    public HealthSystem handle( UpdateHealthSystemEvent event) {
    	entityManager.merge(new HealthSystem(event.getHealthSystemId(), event.getName(), event.getLegalName(), event.getHeadquartersCountry(), event.getWebsite(), event.getFacilities(), event.getSuppliers()));
    }
    
    /*
     * @param	event DeleteHealthSystemEvent
     */
    @EventHandler
    public void on( DeleteHealthSystemEvent event) {
    	HealthSystem entity = new HealthSystem();
   
    	// ------------------------------------------
    	// apply the HealthSystemId
    	// ------------------------------------------
    	entity.setHealthSystemId( event.getHealthSystemId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final HealthSystemRepository healthSystemEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(HealthSystemEventHandler.class.getName());

}
